class Solution:
    def readMeter(self, text: str) -> int:
        n, i = len(text), 0
        while i < n and text[i] == " ":
            i += 1
        sign = 1
        if i < n and text[i] in "+-":
            sign = -1 if text[i] == "-" else 1
            i += 1
        cap, value, seen = 1 << 31, 0, False
        while i < n:
            c = text[i]
            if c.isdigit():
                value = min(cap, value * 10 + int(c))
                seen = True
            elif not (c == "_" and seen and i + 1 < n and text[i + 1].isdigit()):
                break
            i += 1
        return max(-cap, min(cap - 1, sign * value))

