class Solution {
    public int readMeter(String text) {
        int n = text.length(), i = 0;
        while (i < n && text.charAt(i) == ' ') i++;
        int sign = 1;
        if (i < n && (text.charAt(i) == '+' || text.charAt(i) == '-')) sign = text.charAt(i++) == '-' ? -1 : 1;
        long cap = 1L << 31, value = 0;
        boolean seen = false;
        for (; i < n; i++) {
            char c = text.charAt(i);
            if (Character.isDigit(c)) { value = Math.min(cap, value * 10 + (c - '0')); seen = true; }
            else if (!(c == '_' && seen && i + 1 < n && Character.isDigit(text.charAt(i + 1)))) break;
        }
        return (int) Math.max(-cap, Math.min(cap - 1, sign * value));
    }
}

