        int sign = 1;
        if (i < n && (text[i] == '+' || text[i] == '-')) sign = text[i++] == '-' ? -1 : 1;
        long long cap = 1LL << 31, value = 0;
        bool seen = false;
        for (; i < n; i++) {
            char c = text[i];
            if (isdigit((unsigned char) c)) { value = min(cap, value * 10 + (c - '0')); seen = true; }
            else if (!(c == '_' && seen && i + 1 < n && isdigit((unsigned char) text[i + 1]))) break;
        }
        return (int) max(-cap, min(cap - 1, sign * value));
    }
};

