#include <ctype.h>

int readMeter(char* text) {
    int n = strlen(text), i = 0;
    while (i < n && text[i] == ' ') i++;
    int sign = 1;
    if (i < n && (text[i] == '+' || text[i] == '-')) sign = text[i++] == '-' ? -1 : 1;
    long long cap = 1LL << 31, value = 0;
    bool seen = false;
    for (; i < n; i++) {
        char c = text[i];
        if (isdigit((unsigned char) c)) { value = value * 10 + (c - '0'); if (value > cap) value = cap; seen = true; }
        else if (!(c == '_' && seen && i + 1 < n && isdigit((unsigned char) text[i + 1]))) break;
    }
    long long r = sign * value;
    return (int) (r < -cap ? -cap : r > cap - 1 ? cap - 1 : r);
}
